export const counters = { logical_total: 0, logical_good_total: 0 };
export function onAdmitted() { counters.logical_total++;  }
export function onOutcome(classification) {
  if (classification === 'good') counters.logical_good_total++;
}
export function ratioSince(before) {
  return (counters.logical_good_total - before.logical_good_total)
    / (counters.logical_total - before.logical_total);
}

